'use strict';

// MODULES //

var ln = require( '@stdlib/math/base/special/ln' );
var erf = require( '@stdlib/math/base/special/erf' );
var NINF = require( '@stdlib/constants/float64/ninf' );
var SQRT2 = require( '@stdlib/constants/float64/sqrt-two' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );


// VARIABLES //

var INV_SQRT_TWO = 1 / SQRT2; // 1/sqrt(2)


// MAIN //

/**
* Evaluate the natural logarithm of the CDF for a half-normal distribution with scale parameter `sigma` at a value `x`.
*
* @param {number} x - input value
* @param {PositiveNumber} sigma - scale parameter
* @returns {number} logarithm of cumulative distribution function
*
* @example
* var y = logcdf( 1.0, 1.0 );
* // returns ~-0.382
*
* @example
* var y = logcdf( -1.0, 1.0 );
* // returns -Infinity
*/
function logcdf( x, sigma ) {
	if (
		isnan( x ) ||
		isnan( sigma ) ||
		sigma <= 0.0
	) {
		return NaN;
	}
	if ( x < 0.0 ) {
		return NINF;
	}

	return ln( erf( ( x / sigma ) * INV_SQRT_TWO ) );
}


// EXPORTS //

module.exports = logcdf;
